import * as React from 'react';
import { Title, Subtitle, Description, Primary, Controls, Stories, useOf } from '@storybook/blocks';
// Code → Figma conversion of every prop, generated by `pnpm docs:figma-map` (contracts/figma-conversion.json and
// each contract's approved exceptions) — never written by hand.
import figmaMap from '../../../.ai/maps/figma-map.json';

type FigmaProp = { name: string; type: string; values?: string[] };
type Child = { component: string; property: string | null; note?: string; figma?: FigmaProp[] | null };
type FigmaConv = { figma: FigmaProp[] | null; codeOnly: boolean; rule: string; why: string; inChild?: Child | Child[] };
const MAP = figmaMap.components as Record<string, Record<string, FigmaConv>>;

const cell: React.CSSProperties = { padding: 'var(--helix-spacing-s) var(--helix-spacing-m)', borderTop: '1px solid hsla(203, 50%, 30%, 0.15)', verticalAlign: 'top', fontSize: 13, lineHeight: '20px' };
const code: React.CSSProperties = { fontFamily: 'ui-monospace, Menlo, monospace', fontSize: 12, background: 'hsla(203, 50%, 30%, 0.06)', border: '1px solid hsla(203, 50%, 30%, 0.12)', borderRadius: 3, padding: '0 var(--helix-spacing-2xs)', whiteSpace: 'nowrap' };

/** Every prop of the component, with the Figma property it becomes — or "Code only" and why. */
function CodeToFigma() {
  const meta = useOf('meta', ['meta']);
  const name = String(meta.preparedMeta.title ?? '').split('/').pop() ?? '';
  const conv = MAP[name];
  if (!conv) return null;
  // Same order as the props table right above it (Storybook's argTypes for this component), read at render time —
  // a prop added, removed, renamed or moved shows here in its new place with nothing to update by hand. A prop
  // Storybook doesn't list (rare) goes at the end, in the generated map's order.
  // Exactly the rows of the props table right above it (the primary story's argTypes, minus the ones hidden from the
  // table), in its order — read at render time, so adding, removing, renaming or moving a prop changes both tables.
  type ArgType = { table?: { disable?: boolean } };
  let primary: Record<string, ArgType> | undefined;
  try { primary = (useOf('story', ['story']) as { story: { argTypes?: Record<string, ArgType> } }).story.argTypes; } catch { primary = undefined; }
  const argTypes = primary ?? ((meta.preparedMeta as { argTypes?: Record<string, ArgType> }).argTypes ?? {});
  const shown = Object.entries(argTypes).filter(([, a]) => !a?.table?.disable).map(([k]) => k);
  const missing = (prop: string): FigmaConv => ({ figma: null, codeOnly: true, rule: 'missing', why: `not in contracts/components/${name}.json — add it there so it converts (pnpm docs:figma-map)` });
  const props = Object.fromEntries(shown.map(k => [k, conv[k] ?? missing(k)]));
  return (
    <>
      <h3 id="code-to-figma">Code → Figma</h3>
      <p style={{ fontSize: 14 }}>How each prop reaches Figma: 🎨 the Figma property it becomes — on the component itself, or on the nested child component that holds it — or 👾 code only: no design property, and why. Generated from <code>contracts/figma-conversion.json</code> by <code>pnpm docs:figma-map</code>.</p>
      <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
        <thead>
          <tr>{['Prop', 'Figma', 'Why'].map(h => <th key={h} style={{ ...cell, borderTop: 'none', fontWeight: 700 }}>{h}</th>)}</tr>
        </thead>
        <tbody>
          {Object.entries(props).map(([prop, c]) => (
            <tr key={prop}>
              <td style={{ ...cell, fontWeight: 700 }}>{prop}</td>
              <td style={cell}>
                {/* the component's own Figma property, then every child that holds the rest of it */}
                {c.figma?.map(f => (
                  <div key={f.name}>🎨 <span style={code}>{f.type} {f.name}</span>{f.values ? ` = ${f.values.join(' / ')}` : ''}</div>
                ))}
                {[c.inChild ?? []].flat().map(k => (
                  <div key={k.component + (k.property ?? '')}>🎨 On the child <strong>{k.component}</strong>{(k.figma ?? []).map(f => (
                    <span key={f.name}> · <span style={code}>{f.type === 'INSTANCE' ? 'instance' : `${f.type} ${f.name}`}</span>{f.values ? ` = ${f.values.join(' / ')}` : ''}</span>
                  ))}{k.note ? <span style={{ opacity: 0.7 }}> — {k.note}</span> : null}</div>
                ))}
                {!c.figma?.length && !c.inChild ? <span>👾 Code only</span> : null}
              </td>
              <td style={cell}>{c.why}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </>
  );
}

/** Storybook's default docs page, plus the Code → Figma table right after the props table. */
export function FigmaDocsPage() {
  return (
    <>
      <Title />
      <Subtitle />
      <Description />
      <Primary />
      <Controls />
      <CodeToFigma />
      <Stories />
    </>
  );
}
